#include <bits/stdc++.h>
#define HUGE_INF 17446744073709551616ULL
#define ULL_T unsigned long long
using namespace std;

ULL M, N, K, dp_table[18][250005];
ULL fact[250005], inv_fact[250005];

ULL fastExponent(ULL_T base, ULL_T exp) {
    ULL_T res = 1ULL, cur = base;
    while (exp > 0) {
        if (exp & 1ULL) res = (res * cur) % M;
        cur = (cur * cur) % M;
        exp >>= 1ULL;
    }
    return res;
}

ULL nChoose(int a, int b) {
    return (((fact[a] * inv_fact[b]) % M) * inv_fact[a - b]) % M;
}

ULL compute() {
    int i, j, mask;
    fact[0] = 1ULL;
    for (i = 1; i <= N; i++) {
        fact[i] = (fact[i - 1] * (ULL)i) % M;
    }
    inv_fact[N] = fastExponent(fact[N], M - 2ULL);
    for (i = N - 1; i >= 0; i--) {
        inv_fact[i] = (inv_fact[i + 1] * (ULL)(i + 1)) % M;
    }
    for (i = 1; i <= N; i++) {
        dp_table[1][i] = inv_fact[i];
    }
    ULL total = dp_table[1][N] * nChoose(K, 1) % M;
    int limit = min(17, (int)K);
    for (i = 2; i <= limit; i++) {
        for (j = N; j > 0; j = (j - 1) & N) {
            if (dp_table[i - 1][j] == 0) continue;
            int rem_mask = N ^ j;
            for (mask = rem_mask; mask > 0; mask = (mask - 1) & rem_mask) {
                dp_table[i][j + mask] += dp_table[i - 1][j] * inv_fact[mask];
                if (dp_table[i][j + mask] > HUGE_INF) dp_table[i][j + mask] %= M;
            }
        }
        for (j = N; j > 0; j = (j - 1) & N) {
            dp_table[i][j] %= M;
        }
        total += dp_table[i][N] * nChoose(K, i);
        total %= M;
    }
    total *= fact[N];
    total %= M;
    return total;
}

int main() {
    cin >> N >> K >> M;
    ULL res = fastExponent(K, N);
    if (N % 2 == 0) {
        res = (res - compute() + M) % M;
    }
    cout << res << endl;
    return 0;
}
